'use strict';

/*
 * Read-only access to the lightweight UI projection generated by the Python
 * worker. The canonical result.json stays server-side for export/split/batch
 * consumers; browser result APIs only read these compact artifacts.
 */

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const readline = require('readline');
const zlib = require('zlib');

const UI_DIRNAME = 'ui';
const SUMMARY_FILE = 'summary.json';
const VOUCHERS_FILE = 'vouchers.ndjson';
const FINDINGS_FILE = 'findings.json';
const DETAILS_FILE = 'details.bin';
const DETAILS_INDEX_FILE = 'details.idx.json';
const REQUIRED_FILES = [
  SUMMARY_FILE,
  VOUCHERS_FILE,
  FINDINGS_FILE,
  DETAILS_FILE,
  DETAILS_INDEX_FILE
];
const DEFAULT_PAGE_SIZE = 50;
const MAX_PAGE_SIZE = 200;
const DEFAULT_LEGACY_MAX_BYTES = 32 * 1024 * 1024;
const CACHE_LIMIT = 2;
const MAX_SUMMARY_BYTES = 2 * 1024 * 1024;
const MAX_ROWS_BYTES = 512 * 1024 * 1024;
const MAX_FINDINGS_BYTES = 128 * 1024 * 1024;
const MAX_INDEX_BYTES = 256 * 1024 * 1024;
const MAX_DETAIL_BYTES = 8 * 1024 * 1024;
const MAX_DETAIL_INFLATED_BYTES = 32 * 1024 * 1024;

const caches = new Map();
const APP_ROOT = path.resolve(__dirname, '..', '..');

class ProjectionError extends Error {
  constructor(message, status = 409) {
    super(message);
    this.status = status;
  }
}

function uiDirFor(storageRoot, jobId) {
  return path.join(storageRoot, String(jobId), UI_DIRNAME);
}

function isFile(file) {
  try {
    const stat = fs.lstatSync(file);
    return stat.isFile() && !stat.isSymbolicLink();
  } catch (_) {
    return false;
  }
}

function projectionReady(uiDir) {
  return REQUIRED_FILES.every((name) => isFile(path.join(uiDir, name)));
}

function signature(uiDir) {
  try {
    const stat = fs.lstatSync(path.join(uiDir, SUMMARY_FILE));
    return `${stat.mtimeMs}:${stat.size}`;
  } catch (_) {
    return null;
  }
}

function readJson(file, maxBytes) {
  let stat;
  try {
    stat = fs.lstatSync(file);
  } catch (_) {
    throw new ProjectionError('结果索引文件不存在。', 410);
  }
  if (!stat.isFile() || stat.isSymbolicLink()) {
    throw new ProjectionError('结果索引文件不安全。', 410);
  }
  if (stat.size > maxBytes) {
    throw new ProjectionError('结果索引文件异常。', 409);
  }
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (_) {
    throw new ProjectionError('结果索引无法读取。', 409);
  }
}

function cacheFor(jobId, uiDir) {
  const id = String(jobId);
  const current = signature(uiDir);
  if (!current) throw new ProjectionError('结果索引尚未生成。', 409);
  let entry = caches.get(id);
  if (!entry || entry.dir !== uiDir || entry.signature !== current) {
    entry = { id, dir: uiDir, signature: current, summary: null, rows: null, findings: null, index: null };
    caches.set(id, entry);
  }
  caches.delete(id);
  caches.set(id, entry);
  while (caches.size > CACHE_LIMIT) {
    const oldest = caches.keys().next().value;
    caches.delete(oldest);
  }
  return entry;
}

function summary(jobId, uiDir) {
  const entry = cacheFor(jobId, uiDir);
  if (!entry.summary) {
    entry.summary = readJson(path.join(uiDir, SUMMARY_FILE), MAX_SUMMARY_BYTES);
  }
  return entry.summary;
}

function findingRows(jobId, uiDir) {
  const entry = cacheFor(jobId, uiDir);
  if (!entry.findings) {
    const rows = readJson(path.join(uiDir, FINDINGS_FILE), MAX_FINDINGS_BYTES);
    if (!Array.isArray(rows)) throw new ProjectionError('结果索引格式异常。', 409);
    entry.findings = rows;
  }
  return entry.findings;
}

function detailIndex(jobId, uiDir) {
  const entry = cacheFor(jobId, uiDir);
  if (!entry.index) {
    const index = readJson(path.join(uiDir, DETAILS_INDEX_FILE), MAX_INDEX_BYTES);
    if (!index || typeof index !== 'object' || Array.isArray(index)) {
      throw new ProjectionError('结果索引格式异常。', 409);
    }
    entry.index = index;
  }
  return entry.index;
}

function readDetail(jobId, uiDir, voucherKey) {
  const index = detailIndex(jobId, uiDir);
  if (!Object.prototype.hasOwnProperty.call(index, voucherKey)) {
    throw new ProjectionError('凭证不存在。', 404);
  }
  const range = index[voucherKey];
  if (
    !Array.isArray(range)
    || range.length !== 2
    || !Number.isInteger(range[0])
    || !Number.isInteger(range[1])
    || range[0] < 0
    || range[1] <= 0
    || range[1] > MAX_DETAIL_BYTES
  ) {
    throw new ProjectionError('凭证索引异常。', 409);
  }
  const file = path.join(uiDir, DETAILS_FILE);
  let fd;
  try {
    fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
    const stat = fs.fstatSync(fd);
    if (range[0] + range[1] > stat.size) {
      throw new ProjectionError('凭证索引异常。', 409);
    }
    const buffer = Buffer.allocUnsafe(range[1]);
    const read = fs.readSync(fd, buffer, 0, range[1], range[0]);
    if (read !== range[1]) throw new ProjectionError('凭证索引异常。', 409);
    const raw = zlib.inflateSync(buffer, { maxOutputLength: MAX_DETAIL_INFLATED_BYTES });
    return JSON.parse(raw.toString('utf8'));
  } catch (error) {
    if (error instanceof ProjectionError) throw error;
    throw new ProjectionError('凭证索引无法读取。', 409);
  } finally {
    if (fd !== undefined) {
      try { fs.closeSync(fd); } catch (_) {}
    }
  }
}

function invalidate(jobId) {
  caches.delete(String(jobId));
}

function pythonBin(root) {
  const explicit = process.env.JOURNAL_ENTRY_PYTHON_BIN || process.env.PYTHON_BIN;
  if (explicit) {
    if (explicit.startsWith('./') || explicit.startsWith('../')) {
      return path.resolve(root, explicit);
    }
    return explicit;
  }
  const venv = path.join(root, '.venv', 'bin', 'python');
  if (fs.existsSync(venv)) return venv;
  const appVenv = path.join(APP_ROOT, '.venv', 'bin', 'python');
  if (fs.existsSync(appVenv)) return appVenv;
  return 'python3';
}

function legacyMaxBytes() {
  const value = Number(
    process.env.JOURNAL_ENTRY_LEGACY_PROJECTION_MAX_BYTES
      || DEFAULT_LEGACY_MAX_BYTES
  );
  return Number.isFinite(value) && value >= 0 ? value : DEFAULT_LEGACY_MAX_BYTES;
}

function ensureProjection({ root, jobId, jobDir, resultFile }) {
  const uiDir = path.join(jobDir, UI_DIRNAME);
  if (projectionReady(uiDir)) return uiDir;
  if (!resultFile || !isFile(resultFile)) {
    throw new ProjectionError('结果文件已过期，请重新分析。', 410);
  }
  let size;
  try { size = fs.statSync(resultFile).size; } catch (_) {
    throw new ProjectionError('结果文件已过期，请重新分析。', 410);
  }
  if (size > legacyMaxBytes()) {
    throw new ProjectionError(
      '该历史任务结果较大，尚未生成轻量索引；请重新分析后查看。',
      409
    );
  }
  const env = {
    ...process.env,
    PYTHONPATH: [root, APP_ROOT, process.env.PYTHONPATH].filter(Boolean).join(path.delimiter)
  };
  const built = spawnSync(
    pythonBin(root),
    [
      '-m', 'services.journal_entry.ui_projection',
      '--result', resultFile,
      '--output-dir', uiDir
    ],
    { cwd: root, env, encoding: 'utf8', timeout: 120000, maxBuffer: 2 * 1024 * 1024 }
  );
  if (built.error || built.status !== 0 || !projectionReady(uiDir)) {
    throw new ProjectionError('结果索引生成失败，请重新分析。', 409);
  }
  invalidate(jobId);
  return uiDir;
}

function parsePage(value) {
  const page = Number(value);
  if (!Number.isInteger(page) || page < 1) return 1;
  return Math.min(page, 1000000);
}

function parsePageSize(value) {
  const size = Number(value);
  if (!Number.isInteger(size) || size < 1) return DEFAULT_PAGE_SIZE;
  return Math.min(size, MAX_PAGE_SIZE);
}

function pageResult(rows, query) {
  const page = parsePage(query.page);
  const pageSize = parsePageSize(query.pageSize);
  const total = rows.length;
  const totalPages = total ? Math.ceil(total / pageSize) : 0;
  const start = (page - 1) * pageSize;
  return {
    rows: rows.slice(start, start + pageSize),
    total,
    page,
    pageSize,
    totalPages
  };
}

function textFilter(value, max = 200) {
  if (value === undefined || value === null) return '';
  return String(value).slice(0, max);
}

function riskRank(value) {
  return ({ HIGH: 3, MEDIUM: 2, LOW: 1, INFO: 0 })[String(value || '').toUpperCase()] ?? -1;
}

function voucherComparator(sort) {
  if (sort === 'riskScore') {
    return (a, b) => (
      (Number(b.rs) || 0) - (Number(a.rs) || 0)
      || String(a.k).localeCompare(String(b.k))
    );
  }
  return (a, b) => (
    riskRank(b.rl) - riskRank(a.rl)
    || (Number(b.rs) || 0) - (Number(a.rs) || 0)
    || String(a.k).localeCompare(String(b.k))
  );
}

function voucherMatcher(query) {
  const balance = textFilter(query.balance, 20);
  if (balance && !['all', 'balanced', 'within', 'unbalanced'].includes(balance)) {
    throw new ProjectionError('平衡状态筛选无效。', 400);
  }
  const view = textFilter(query.view, 20);
  if (view && !['business', 'contra'].includes(view)) {
    throw new ProjectionError('视图筛选无效。', 400);
  }
  const businessCode = textFilter(query.businessCode);
  const confidence = textFilter(query.confidence, 20);
  const riskLevel = textFilter(query.riskLevel, 20).toUpperCase();
  const contra = textFilter(query.contra, 20);
  return (row) => {
    if (view === 'business' && !row.bc) return false;
    if (view === 'contra' && !row.rc) return false;
    if (balance === 'balanced' && !row.b) return false;
    if (balance === 'within' && (row.b || !row.w)) return false;
    if (balance === 'unbalanced' && row.w) return false;
    if (businessCode && row.bc !== businessCode) return false;
    if (confidence && row.bcl !== confidence) return false;
    if (riskLevel && String(row.rl || '').toUpperCase() !== riskLevel) return false;
    if (contra === 'allocated' && !(row.ct && row.ct.ca > 0)) return false;
    if (contra === 'unallocated' && !(row.ct && row.ct.cu > 0)) return false;
    if (contra === 'ambiguous' && !(row.ct && row.ct.cf.includes('ambiguous'))) return false;
    if (contra === 'limited' && !(row.ct && (row.ct.cf.includes('limited') || row.ct.cf.includes('solution_limit')))) return false;
    return true;
  };
}

async function queryVouchers(jobId, uiDir, query) {
  const file = path.join(uiDir, VOUCHERS_FILE);
  let stat;
  try { stat = fs.lstatSync(file); } catch (_) {
    throw new ProjectionError('结果索引文件不存在。', 410);
  }
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size > MAX_ROWS_BYTES) {
    throw new ProjectionError('结果索引文件异常。', 409);
  }
  const matches = voucherMatcher(query);
  const page = parsePage(query.page);
  const pageSize = parsePageSize(query.pageSize);
  const sort = textFilter(query.sort, 20);
  if (sort && !['voucher', 'riskScore', 'riskLevel'].includes(sort)) {
    throw new ProjectionError('排序方式无效。', 400);
  }
  if (sort && sort !== 'voucher' && page > 1000) {
    throw new ProjectionError('排序分页超出范围。', 400);
  }
  const start = (page - 1) * pageSize;
  const limit = start + pageSize;
  const compare = sort && sort !== 'voucher' ? voucherComparator(sort) : null;
  let total = 0;
  let pageRows = [];
  let sortedRows = [];
  const stream = readline.createInterface({
    input: fs.createReadStream(file, { encoding: 'utf8' }),
    crlfDelay: Infinity
  });
  try {
    for await (const line of stream) {
      if (!line) continue;
      let row;
      try { row = JSON.parse(line); } catch (_) {
        throw new ProjectionError('结果索引格式异常。', 409);
      }
      if (!row || !matches(row)) continue;
      if (!compare) {
        if (total >= start && total < start + pageSize) pageRows.push(row);
      } else if (sortedRows.length < limit) {
        sortedRows.push(row);
        if (sortedRows.length === limit) sortedRows.sort(compare);
      } else if (compare(row, sortedRows[sortedRows.length - 1]) < 0) {
        sortedRows[sortedRows.length - 1] = row;
        let index = sortedRows.length - 1;
        while (index > 0 && compare(sortedRows[index], sortedRows[index - 1]) < 0) {
          [sortedRows[index - 1], sortedRows[index]] = [sortedRows[index], sortedRows[index - 1]];
          index -= 1;
        }
      }
      total += 1;
    }
  } finally {
    stream.close();
  }
  if (compare) {
    sortedRows.sort(compare);
    pageRows = sortedRows.slice(start, start + pageSize);
  }
  return {
    rows: pageRows,
    total,
    page,
    pageSize,
    totalPages: total ? Math.ceil(total / pageSize) : 0
  };
}

function sortFindings(rows, sort) {
  if (sort === 'riskScore') {
    return rows.slice().sort((a, b) => (
      (Number(b.risk_score) || 0) - (Number(a.risk_score) || 0)
      || String(a.voucher_key).localeCompare(String(b.voucher_key))
      || String(a.code).localeCompare(String(b.code))
    ));
  }
  if (sort === 'riskLevel') {
    return rows.slice().sort((a, b) => (
      riskRank(b.severity) - riskRank(a.severity)
      || (Number(b.risk_score) || 0) - (Number(a.risk_score) || 0)
      || String(a.voucher_key).localeCompare(String(b.voucher_key))
    ));
  }
  return rows;
}

function queryFindings(rows, query) {
  const riskLevel = textFilter(query.riskLevel, 20).toUpperCase();
  const ruleCode = textFilter(query.ruleCode || query.code);
  const businessCode = textFilter(query.businessCode);
  const sort = textFilter(query.sort, 20);
  if (sort && !['default', 'riskScore', 'riskLevel'].includes(sort)) {
    throw new ProjectionError('排序方式无效。', 400);
  }
  const filtered = rows.filter((row) => {
    if (riskLevel && String(row.severity || '').toUpperCase() !== riskLevel) return false;
    if (ruleCode && row.code !== ruleCode) return false;
    if (businessCode && row.business_group !== businessCode) return false;
    return true;
  });
  return pageResult(sortFindings(filtered, sort), query);
}

module.exports = {
  ProjectionError,
  UI_DIRNAME,
  DEFAULT_PAGE_SIZE,
  MAX_PAGE_SIZE,
  DEFAULT_LEGACY_MAX_BYTES,
  uiDirFor,
  projectionReady,
  ensureProjection,
  summary,
  findingRows,
  readDetail,
  queryVouchers,
  queryFindings,
  invalidate,
  parsePage,
  parsePageSize
};
